import './styles/SideButtons.css';

export default function SideButtons() {
    const repeatNo = 13;
    const buttons = [];
    for (let i = 0; i < repeatNo; i++) {
        buttons.push(<button key={i} className='Btn'>button</button>);
    }
    return (
        <div className='Border'>
            {/* {buttons} */}

            <button className='Btn'>button</button>
            <button className='Btn'>button</button>
            <button className='Btn'>button</button>
        </div>
    );
}
